-- Exercise the exact attribution-loader projections under the deployed role.
-- LIMIT 0 validates authority/columns without returning any retained source data.
set local role service_role;
do $$begin
 perform id,recording_id,transcript_text from public.phone_transcripts limit 0;
 perform id,tenant_id,recording_id,created_at from public.phone_ai_insights limit 0;
 perform extension,e164_number,endpoint_ref,person_node_id,role,is_shared_device,
   confidence,source,metadata,tenant_id,active from public.telephony_directory limit 0;
 perform term,category,aliases,phonetic_variants,confidence,tenant_id,active from public.tenant_vocabulary limit 0;
 perform id,from_number,to_number,direction,raw_payload,tenant_id,provider_call_id,linked_id,started_at from public.phone_calls limit 0;
 perform related_person_id,related_company_id,tenant_id,source_table,source_id from public.interactions limit 0;
 perform id,label,node_type,tenant_id from public.graph_nodes limit 0;
 perform id,display_name from public.tenants limit 0;
end$$;
reset role;

rollback to savepoint phone_processing_probe;
release savepoint phone_processing_probe;
do $$begin
 if has_table_privilege('authenticated','public.learn_phone_result_versions','select')
 or has_table_privilege('authenticated','public.learn_phone_processing_attempts','select')
 or has_function_privilege('authenticated','public.learn_phone_derived_attempt(uuid,uuid,uuid,text,text,jsonb)','execute')
 or has_function_privilege('service_role','public.learn_phone_apply_intelligence(uuid,uuid,uuid,uuid,uuid,jsonb)','execute') then raise exception 'Private processing authority leaked';end if;
 if exists(select 1 from public.learn_phone_processing_attempts) or exists(select 1 from public.learn_phone_result_versions)
 or exists(select 1 from public.call_directions) or exists(select 1 from public.call_participants)
 or exists(select 1 from public.call_transcript_normalisations) or exists(select 1 from public.telephony_directory)
 or exists(select 1 from public.tenant_vocabulary) then raise exception 'Unexpected retained fixture';end if;
